import { registerDict } from "./registry";

/**
 * Translations for the Help Center's ARTICLE CONTENT (src/lib/help/content.ts) — every summary,
 * step, note, and subsection across all ~31 categories. Complements dict-help.ts, which only
 * covers this page's own UI chrome (heading, search box, section labels).
 *
 * Keying scheme: every string in content.ts is addressed by `help.content.<categoryId>.<field>
 * [.<index>]`, generated at render time in page.tsx (e.g. `help.content.rental-ps.step2`,
 * `help.content.rental-ps.sub0.step1`, `help.content.rental-ps.sub0.note0`) rather than
 * hand-written per key here — this file only needs to provide the RIGHT-HAND translations for
 * whatever key the page generates from a given category's array index. Group sidebar headings
 * use `help.content.group.<Indonesian group name>`.
 *
 * Deliberately NO "id" entry on any key — content.ts's own Indonesian string is always passed as
 * the `fallback` argument to t() at the call site (see registry.ts's translate(): it falls back
 * to `fallback` when neither the active language nor "id" has a registered entry), so Indonesian
 * never needs to be duplicated here. Only en/ms/th/fil/vi are registered.
 *
 * If content.ts changes (new category, new step, reordered array), the corresponding key here
 * either needs updating or a fresh translation added — same "treat as documentation to keep in
 * sync" caveat content.ts's own header already states. A key with no entry yet simply falls back
 * to the Indonesian text, so nothing breaks/blanks out in the meantime.
 *
 * Full-text SEARCH on this page intentionally still searches the Indonesian source text only
 * (see searchBlob() in page.tsx) regardless of active language — translating the full-text search
 * index too was out of scope for this pass.
 */

