    ms: "manage_devices: Owner, Superuser, Manager, Supervisor (tidak termasuk Cashier/Accountant/Kitchen).",
    th: "manage_devices: Owner, Superuser, Manager, Supervisor (ไม่รวม Cashier/Accountant/Kitchen)",
    fil: "manage_devices: Owner, Superuser, Manager, Supervisor (hindi kasama ang Cashier/Accountant/Kitchen).",
